1455	// TestRestoreRejectsPolicyCumulativeQuotaOverflow 验证预留与已花费各自都能
1456	// 由 int64 表示、合计却越过 int64 上限时必须拒绝，不能因金额越界误判为
1457	// 额度充足。
1458	func TestRestoreRejectsPolicyCumulativeQuotaOverflow(t *testing.T) {
1459		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1460		data := buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1461			id: "p-big", per: math.MaxInt64, total: math.MaxInt64,
1462			reqs: []quotaReqSpec{
1463				{id: "settled", account: "u1", estFee: math.MaxInt64, actualFee: math.MaxInt64, state: RequestSettled},
1464				{id: "reserved", account: "u1", estFee: 1, state: RequestReserved},
1465			},
1466		}})
1467		w2, err := restoreAt(data, t0)
1468		if err == nil {
1469			if w2 != nil {
1470				t.Fatalf("overflowing-quota backup restored a wallet")
1471			}
1472			t.Fatalf("overflowing-quota backup restored without error")
1473		}
1474		if !errors.Is(err, ErrBackupInvalid) {
1475			t.Fatalf("err = %v, want ErrBackupInvalid", err)
1476		}
1477		msg := err.Error()
1478		if !strings.Contains(msg, "p-big") || !strings.Contains(msg, "cumulative total limit") {
1479			t.Fatalf("error %q must name policy and cumulative limit", msg)
1480		}
1481	}
1482	
1483	// TestRestoreAcceptsCumulativeQuotaAtBoundary 验证合计恰好等于累计上限合法，
1484	// 包括上限恰为 int64 最大值的情况；不缩小现有金额范围。
1485	func TestRestoreAcceptsCumulativeQuotaAtBoundary(t *testing.T) {
1486		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1487	
1488		// 上限 50：结算实际 20（预估 30，差额已退回）+ 现存预留 30 = 50。
1489		data := buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1490			id: "p-eq", per: 30, total: 50,
1491			reqs: []quotaReqSpec{
1492				{id: "settled", account: "u1", estFee: 30, actualFee: 20, state: RequestSettled},
1493				{id: "reserved", account: "u1", estFee: 30, state: RequestReserved},
1494			},
1495		}})
1496		if _, err := restoreAt(data, t0); err != nil {
1497			t.Fatalf("used == total restore: %v", err)
1498		}
1499	
1500		// 上限 MaxInt64：已花费 MaxInt64-1 + 预留 1 = MaxInt64。
1501		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1502			id: "p-max", per: math.MaxInt64, total: math.MaxInt64,
1503			reqs: []quotaReqSpec{
1504				{id: "settled", account: "u1", estFee: math.MaxInt64, actualFee: math.MaxInt64 - 1, state: RequestSettled},
1505				{id: "reserved", account: "u1", estFee: 1, state: RequestReserved},
1506			},
1507		}})
1508		if _, err := restoreAt(data, t0); err != nil {
1509			t.Fatalf("used == MaxInt64 restore: %v", err)
1510		}
1511	
1512		// 上限 MaxInt64：单笔已结算实际费用 MaxInt64，占满额度。
1513		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1514			id: "p-spent-max", per: math.MaxInt64, total: math.MaxInt64,
1515			reqs: []quotaReqSpec{
1516				{id: "settled", account: "u1", estFee: math.MaxInt64, actualFee: math.MaxInt64, state: RequestSettled},
1517			},
1518		}})
1519		if _, err := restoreAt(data, t0); err != nil {
1520			t.Fatalf("spent == MaxInt64 restore: %v", err)
1521		}
1522	
1523		// 上限 MaxInt64：单笔预估费用 MaxInt64 的现存预留占满额度。
1524		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1525			id: "p-reserved-max", per: math.MaxInt64, total: math.MaxInt64,
1526			reqs: []quotaReqSpec{
1527				{id: "reserved", account: "u1", estFee: math.MaxInt64, state: RequestReserved},
1528			},
1529		}})
1530		if _, err := restoreAt(data, t0); err != nil {
1531			t.Fatalf("reserved == MaxInt64 restore: %v", err)
1532		}
1533	
1534		// 不同策略分别判断：同一出资账户的两条策略各自恰好占满 50，
1535		// 跨策略合计 100 不影响合法性。
1536		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{
1537			{
1538				id: "p1", per: 100, total: 50,
1539				reqs: []quotaReqSpec{
1540					{id: "s1", account: "u1", estFee: 30, actualFee: 20, state: RequestSettled},
1541					{id: "r1", account: "u1", estFee: 30, state: RequestReserved},
1542				},
1543			},
1544			{
1545				id: "p2", per: 100, total: 50,
1546				reqs: []quotaReqSpec{
1547					{id: "s2", account: "u2", estFee: 30, actualFee: 20, state: RequestSettled},
1548					{id: "r2", account: "u2", estFee: 30, state: RequestReserved},
1549				},
1550			},
1551		})
1552		if _, err := restoreAt(data, t0); err != nil {
1553			t.Fatalf("two policies each at their own limit: %v", err)
1554		}
1555	}
1556	
1557	// TestRestoreCumulativeQuotaIgnoresNonOccupyingStates 验证只有现存预留与已
1558	// 结算实际费用占用累计额度：待审批、审批拒绝、待审批取消、待审批过期、已
1559	// 预留后取消、预留超时的请求都不占用；结算退回的差额也不计入已花费。
1560	func TestRestoreCumulativeQuotaIgnoresNonOccupyingStates(t *testing.T) {
1561		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1562		// 累计上限仅 10：一笔实际费用 10 的已结算请求占满额度；其余请求费用均
1563		// 为 30（待审批系严格超过门槛 10），但都不占用额度，备份仍合法。
1564		data := buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1565			id: "p-free", per: 100, total: 10, threshold: 10,
1566			wait: 5 * time.Minute, reserveDur: time.Minute,
1567			reqs: []quotaReqSpec{
1568				{id: "settled", account: "u1", estFee: 10, actualFee: 10, state: RequestSettled},
1569				{id: "reserved-cancelled", account: "u1", estFee: 10, state: RequestCancelled, wasReserved: true},
1570				{id: "reservation-expired", account: "u1", estFee: 10, state: RequestReservationExpired},
1571				{id: "pending", account: "u1", estFee: 30, state: RequestPendingApproval},
1572				{id: "rejected", account: "u1", estFee: 30, state: RequestRejected, rejectReason: "no"},
1573				{id: "pending-expired", account: "u1", estFee: 30, state: RequestExpired},
1574				{id: "pending-cancelled", account: "u1", estFee: 30, state: RequestCancelled},
1575			},
1576		}})
1577		w2, err := restoreAt(data, t0)
1578		if err != nil {
1579			t.Fatalf("non-counting states restore: %v", err)
1580		}
1581		// 未到期的待审批请求不被改写；没有任何现存预留，账户预留余额为零。
1582		r, err := w2.Request("u1", "pending")
1583		if err != nil || r.State != RequestPendingApproval {
1584			t.Fatalf("pending request state = %v err = %v, want still pending", r.State, err)
1585		}
1586		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 0, Reserved: 0}) {
1587			t.Fatalf("payer balance = %+v, want zero reserved", bal)
1588		}
1589	}
1590	
1591	// ---- 并发 ----
1592	
1593	func TestExportConcurrentWithMutations(t *testing.T) {
1594		w, c := newTestWallet()
1595		t0 := c.t
1596		mustAccount(t, w, "payer", 1_000_000)
1597		mustAccount(t, w, "u1", 0)
1598		mustAccount(t, w, "u2", 0)
1599		if _, err := w.CreateSession("s1", "u1", "dev1", t0.Add(24*time.Hour)); err != nil {
1600			t.Fatal(err)
1601		}
1602		if _, err := w.CreateSession("s2", "u2", "dev2", t0.Add(24*time.Hour)); err != nil {
1603			t.Fatal(err)
1604		}
1605		if err := w.SavePolicy(PolicySpec{
1606			ID: "p1", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
1607			Operation: "charge", Payee: "shop",
1608			StartsAt: t0.Add(-time.Hour), EndsAt: t0.Add(24 * time.Hour),
1609			MaxPerRequest: 100, MaxTotal: 1_000_000,
1610			MaxReserveDuration: time.Hour,
1611		}); err != nil {
1612			t.Fatal(err)
1613		}
1614	
1615		const n = 200
1616		var wg sync.WaitGroup
1617		var backups [][]byte
1618		var mu sync.Mutex
1619	
1620		// 申请/结算/取消/导出 并发；每个备份都必须是可恢复的完整状态。
1621		for g := 0; g < 4; g++ {
1622			g := g
1623			wg.Add(1)
1624			go func() {
1625				defer wg.Done()
1626				for i := 0; i < n; i++ {
1627					rid := fmt.Sprintf("g%d-r%d", g, i)
1628					in := RequestInput{
1629						PolicyID: "p1", RequestID: rid, AccountID: "u2", SessionID: "s2",
1630						DeviceID: "dev2", Operation: "charge", Payee: "shop", EstimatedFee: 1,
1631					}
1632					if _, err := w.Apply(in); err != nil {
1633						t.Errorf("apply: %v", err)
1634						return
1635					}
1636					switch i % 3 {
1637					case 0:
1638						if _, err := w.Settle("u2", rid, 1); err != nil {
1639							t.Errorf("settle: %v", err)
1640						}
1641					case 1:
1642						if _, err := w.Cancel("u2", rid); err != nil {
1643							t.Errorf("cancel: %v", err)
1644						}
1645					}
1646				}
1647			}()
1648		}
1649		wg.Add(1)
1650		go func() {
1651			defer wg.Done()
1652			for i := 0; i < n; i++ {
1653				data, err := w.Export()
1654				if err != nil {
1655					t.Errorf("export: %v", err)
1656					return
1657				}
1658				mu.Lock()
1659				backups = append(backups, data)
1660				mu.Unlock()
1661			}
1662		}()
1663		wg.Wait()
1664	
1665		if len(backups) == 0 {
1666			t.Fatal("no backups captured")
1667		}
1668		for i, data := range backups {
1669			w2, err := Restore(data)
1670			if err != nil {
1671				t.Fatalf("backup %d not restorable: %v", i, err)
1672			}
1673			// 恢复出的钱包余额自洽：非负且预留不凭空消失。
1674			for _, id := range []string{"payer"} {
1675				bal, err := w2.Balance(id)
1676				if err != nil {
1677					t.Fatalf("backup %d balance: %v", i, err)
1678				}
1679				if bal.Available < 0 || bal.Reserved < 0 {
1680					t.Fatalf("backup %d negative balance: %+v", i, bal)
1681				}
1682			}
1683		}
1684	
1685		// 最终状态本身也必须可导出/恢复且账本完整（用与源钱包相同的受控时刻，
1686		// 避免恢复时钟把未到期预留结算掉而混淆比较）。
1687		final, err := w.Export()
1688		if err != nil {
1689			t.Fatal(err)
1690		}
1691		w2, err := restoreAt(final, c.t)
1692		if err != nil {
1693			t.Fatal(err)
1694		}
1695		if l1, l2 := len(w.Ledger()), len(w2.Ledger()); l1 != l2 {
1696			t.Fatalf("final ledger length = %d, want %d", l2, l1)
1697		}
1698	}
