748			t.Fatal(err)
749		}
750		c2.t = c2.t.Add(30 * time.Second)
751		if _, err := w2.Cancel("u1", "r2"); err != nil {
752			t.Fatal(err)
753		}
754		c2.t = c2.t.Add(time.Hour)
755		if r, _ := w2.Request("u1", "r2"); r.State != RequestCancelled {
756			t.Fatalf("cancelled request rewritten: %v", r.State)
757		}
758		if n := countKind(w2.Ledger(), LedgerReservationExpiration); n != 0 {
759			t.Fatalf("cancelled request produced timeout entries: %d", n)
760		}
761	}
762	
763	func TestConcurrentSettleCancelTimeoutSingleRefund(t *testing.T) {
764		for iter := 0; iter < 50; iter++ {
765			w, c := setupTimeout(t, time.Minute)
766			in := timeoutApply()
767			in.RequestID = fmt.Sprintf("race-%d", iter)
768			if _, err := w.Apply(in); err != nil {
769				t.Fatal(err)
770			}
771			c.t = c.t.Add(time.Minute) // 所有操作都在截止时刻及之后进入
772	
773			const n = 12
774			var wg sync.WaitGroup
775			wg.Add(n)
776			for i := 0; i < n; i++ {
777				i := i
778				go func() {
779					defer wg.Done()
780					switch i % 3 {
781					case 0:
782						_, _ = w.Settle("u1", fmt.Sprintf("race-%d", iter), 20)
783					case 1:
784						_, _ = w.Cancel("u1", fmt.Sprintf("race-%d", iter))
785					case 2:
786						_, _ = w.Request("u1", fmt.Sprintf("race-%d", iter))
787					}
788				}()
789			}
790			wg.Wait()
791	
792			req, _ := w.Request("u1", fmt.Sprintf("race-%d", iter))
793			if req.State != RequestReservationExpired {
794				t.Fatalf("iter %d: state = %v, want reservation expired", iter, req.State)
795			}
796			// 退款只能发生一次，超时留痕只能一条。
797			if n := countKind(w.Ledger(), LedgerRefund); n != 1 {
798				t.Fatalf("iter %d: refund entries = %d, want 1", iter, n)
799			}
800			if n := countKind(w.Ledger(), LedgerReservationExpiration); n != 1 {
801				t.Fatalf("iter %d: timeout entries = %d, want 1", iter, n)
802			}
803			if bal, _ := w.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
804				t.Fatalf("iter %d: balance = %+v", iter, bal)
805			}
806			pv, _ := w.Policy("p-timeout")
807			if pv.ReservedTotal != 0 || pv.SpentTotal != 0 {
808				t.Fatalf("iter %d: totals = %+v", iter, pv)
809			}
810		}
811	}
