824		next.RequestID = "r2"
825		if _, err := w.Apply(next); err != nil {
826			t.Fatal(err)
827		}
828		// 迟到结算旧请求：超时错误，不能扣走已被 r2 使用的费用。
829		if _, err := w.Settle("u1", "r1", 20); !errors.Is(err, ErrReservationExpired) {
830			t.Fatalf("late settle err = %v, want ErrReservationExpired", err)
831		}
832		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 80, Reserved: 20}) {
833			t.Fatalf("balance = %+v, want {80 20}", bal)
834		}
835		// 新请求仍可正常结算。
836		if _, err := w.Settle("u1", "r2", 20); err != nil {
837			t.Fatalf("new request settle: %v", err)
838		}
839		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 80, Reserved: 0}) {
