200	// buildApproveOverflowBackup 构造批准溢出场景的自洽备份：
201	//   - 策略 p-big 单次/累计上限均为 MaxInt64，门槛 1、等待 1 小时，
202	//     最长预留时长 reserveDur（零表示关闭预留超时）；
203	//   - u1 一笔已结算实际费用 1（已花费 1，直接受理路径）；
204	//   - u2 一笔现存预留 big，预估 MaxInt64-2（批准路径，带批准信息），
205	//     预留时刻 t0、截止 t0+reserveDur；
206	//   - u1 一笔待审批 small，预估费用 2，提交于 t0，等待截止 t0+1h；
207	//   - 出资账户 payer 可用余额 2、预留余额 MaxInt64-2（可用+预留恰为
208	//     MaxInt64，备份自洽），现存预留与已花费合计 MaxInt64-1：再计入
209	//     small 的 2 会越过 int64 上限；
210	//   - 另有出资账户会话 sa（设备 dev-approve）供批准使用。
211	func buildApproveOverflowBackup(t *testing.T, t0 time.Time, reserveDur time.Duration) []byte {
212		t.Helper()
213		const (
214			spentActual = 1
215			bigFee      = math.MaxInt64 - 2
216			smallFee    = 2
217		)
218		settled := requestBackupV1{
219			PolicyID: "p-big", RequestID: "settled", AccountID: "u1", PayerAccountID: "payer",
220			SessionID: "s1", Operation: "charge", Payee: "shop",
221			EstimatedFee: spentActual, ActualFee: spentActual,
222			State:      int(RequestSettled),
223			CreatedAt:  timeJSON(t0.Add(-2 * time.Hour)),
224			ReservedAt: timeJSON(t0.Add(-2 * time.Hour)),
225			SettledAt:  timeJSON(t0.Add(-time.Hour)),
226		}
227		big := requestBackupV1{
228			PolicyID: "p-big", RequestID: "big", AccountID: "u2", PayerAccountID: "payer",
229			SessionID: "s2", Operation: "charge", Payee: "shop",
230			EstimatedFee:      bigFee,
231			State:             int(RequestReserved),
232			CreatedAt:         timeJSON(t0),
233			WaitDeadline:      timeJSON(t0.Add(time.Hour)),
234			ReservedAt:        timeJSON(t0),
235			ReserveDuration:   durationJSON(reserveDur),
236			ApproverAccountID: "payer",
237			DecidedAt:         timeJSON(t0),
238		}
239		if reserveDur > 0 {
240			big.ReserveDeadline = timeJSON(t0.Add(reserveDur))
241		}
242		small := requestBackupV1{
243			PolicyID: "p-big", RequestID: "small", AccountID: "u1", PayerAccountID: "payer",
244			SessionID: "s1", Operation: "charge", Payee: "shop",
245			EstimatedFee: smallFee,
246			State:        int(RequestPendingApproval),
247			CreatedAt:    timeJSON(t0),
248			WaitDeadline: timeJSON(t0.Add(time.Hour)),
249		}
250		// 已结算请求的预留时长快照必须与策略一致（备份自洽要求）。
251		settled.ReserveDuration = durationJSON(reserveDur)
252		if reserveDur > 0 {
253			settled.ReserveDeadline = timeJSON(t0.Add(-2 * time.Hour).Add(reserveDur))
254		}
255		b := backupV1{
256			Version:    backupVersion,
257			ExportedAt: timeJSON(t0),
258			Accounts: []accountBackupV1{
259				{ID: "payer", Available: 2, Reserved: bigFee, CreatedAt: timeJSON(t0)},
260				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
261				{ID: "u2", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
262			},
263			Sessions: []sessionBackupV1{
264				{ID: "s1", AccountID: "u1", DeviceID: "d1", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
265				{ID: "s2", AccountID: "u2", DeviceID: "d2", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
266				{ID: "sa", AccountID: "payer", DeviceID: "dev-approve", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
267			},
268			Policies: []policyBackupV1{{
269				ID: "p-big", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
270				Operation: "charge", Payee: "shop",
271				StartsAt: timeJSON(t0.Add(-time.Hour)), EndsAt: timeJSON(t0.Add(24 * time.Hour)),
272				MaxPerRequest:      math.MaxInt64,
273				MaxTotal:           math.MaxInt64,
274				ApprovalThreshold:  1,
275				ApprovalWait:       durationJSON(time.Hour),
276				MaxReserveDuration: durationJSON(reserveDur),
277				ReservedTotal:      bigFee,
278				SpentTotal:         spentActual,
279			}},
280			Requests: []requestBackupV1{settled, big, small},
281			Ledger:   []ledgerEntryBackupV1{},
282		}
283		data, err := json.Marshal(&b)
284		if err != nil {
285			t.Fatal(err)
286		}
287		return data
288	}
