295	// TestApproveSharedQuotaOverflowKeepsPending 验证待审批请求批准前重新执行
296	// 溢出安全的累计额度判断：其他请求已占用额度使本次批准越过 int64 上限时，
297	// 批准返回 ErrQuotaExceeded，请求继续待审批，提交时间、等待截止时间与决定
298	// 信息不变，不开始预留计时、不新增预留或批准记录；取消释放额度后期限内仍
299	// 可再次批准。
300	func TestApproveSharedQuotaOverflowKeepsPending(t *testing.T) {
301		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
302		data := buildApproveOverflowBackup(t, t0, 0)
303		w, err := restoreAt(data, t0)
304		if err != nil {
305			t.Fatalf("restore: %v", err)
306		}
307		before, err := w.Request("u1", "small")
308		if err != nil {
309			t.Fatal(err)
310		}
311		if before.State != RequestPendingApproval {
312			t.Fatalf("setup state = %v, want pending", before.State)
313		}
314		// 余额恰好够（2），但额度合计 MaxInt64-1 再加 2 越过 int64 上限。
315		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 2, Reserved: math.MaxInt64 - 2}) {
316			t.Fatalf("setup balance = %+v", bal)
317		}
318	
319		ledgerBefore := len(w.Ledger())
320		if _, err := approveSmall(w); !errors.Is(err, ErrQuotaExceeded) {
321			t.Fatalf("approve err = %v, want ErrQuotaExceeded", err)
322		}
323	
324		// 请求继续待审批，提交时间、等待截止时间与已有决定信息保持不变。
325		req, _ := w.Request("u1", "small")
326		if req.State != RequestPendingApproval {
327			t.Fatalf("state = %v, want still pending approval", req.State)
328		}
329		if !req.CreatedAt.Equal(before.CreatedAt) || !req.WaitDeadline.Equal(before.WaitDeadline) {
330			t.Fatalf("timing changed: created %v->%v deadline %v->%v",
331				before.CreatedAt, req.CreatedAt, before.WaitDeadline, req.WaitDeadline)
332		}
333		if !req.DecidedAt.Equal(time.Time{}) || req.ApproverAccountID != "" || req.RejectReason != "" {
334			t.Fatalf("decision fields changed on failed approve: %+v", req)
335		}
336		// 不开始预留计时。
337		if !req.ReservedAt.Equal(time.Time{}) || req.ReserveDuration != 0 || !req.ReserveDeadline.Equal(time.Time{}) {
338			t.Fatalf("reserve timing started on failed approve: %+v", req)
339		}
340		// 不新增预留或批准记录，余额与额度不变。
341		if got := len(w.Ledger()); got != ledgerBefore {
342			t.Fatalf("ledger grew by %d on failed approve", got-ledgerBefore)
343		}
344		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 2, Reserved: math.MaxInt64 - 2}) {
345			t.Fatalf("balance changed after failed approve: %+v", bal)
346		}
347		pv, _ := w.Policy("p-big")
348		if pv.ReservedTotal != math.MaxInt64-2 || pv.SpentTotal != 1 {
349			t.Fatalf("policy totals changed after failed approve: %+v", pv)
350		}
351	
352		// 期限内额度未释放时再次批准仍被拒绝。
353		if _, err := approveSmall(w); !errors.Is(err, ErrQuotaExceeded) {
354			t.Fatalf("second approve err = %v, want ErrQuotaExceeded", err)
355		}
356	
357		// 取消 u2 的大额预留，释放 MaxInt64-2 共享额度并全额退回余额。
358		if _, err := w.Cancel("u2", "big"); err != nil {
359			t.Fatal(err)
360		}
361		if bal, _ := w.Balance("payer"); bal != (Balances{Available: math.MaxInt64, Reserved: 0}) {
362			t.Fatalf("balance after cancel big = %+v", bal)
363		}
364		// 仍在等待期限内（时钟停在 t0，截止 t0+1h），释放后批准成功并预留 2。
365		req, err = approveSmall(w)
366		if err != nil {
367			t.Fatalf("approve after quota freed: %v", err)
368		}
369		if req.State != RequestReserved {
370			t.Fatalf("state = %v, want reserved", req.State)
371		}
372		if bal, _ := w.Balance("payer"); bal != (Balances{Available: math.MaxInt64 - 2, Reserved: 2}) {
373			t.Fatalf("balance after approve small = %+v", bal)
374		}
375		pv, _ = w.Policy("p-big")
376		if pv.ReservedTotal != 2 || pv.SpentTotal != 1 {
377			t.Fatalf("policy totals after approve small = %+v", pv)
378		}
379	}
