413		if err != nil {
414			t.Fatalf("approve after timeout release: %v", err)
415		}
416		if req.State != RequestReserved {
417			t.Fatalf("state = %v, want reserved", req.State)
418		}
419		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: math.MaxInt64 - 2, Reserved: 2}) {
420			t.Fatalf("balance after approve small = %+v", bal)
421		}
422		pv, _ := w2.Policy("p-big")
423		if pv.ReservedTotal != 2 || pv.SpentTotal != 1 {
424			t.Fatalf("policy totals = %+v", pv)
