466		// 额度已占满：再申请费用 1 必须超额度拒绝（used+1 越过 int64 上限；
467		// 余额虽同样不足，但额度判断在前，仍返回 ErrQuotaExceeded）。
468		in.RequestID = "one-more"
469		in.EstimatedFee = 1
470		if _, err := w.Apply(in); !errors.Is(err, ErrQuotaExceeded) {
471			t.Fatalf("apply after quota full err = %v, want ErrQuotaExceeded", err)
472		}
473	}
